        let source = "module static.writer; @id(\"generic\") fn generic<T>(value:T)->T {let key=str\"x\";let mut at=0;while at<2 {at=at+1;if at==1 {continue;};0};value} @id(\"app.main\") fn main()->i64 {0}";
